input.new_string:
table{width:100%;border-collapse:collapse;font-size:12.5px}
code{background:#0e1526;border:1px solid var(--border-soft);border-radius:5px;padding:1px 5px;font-family:Consolas,"Courier New",monospace;font-size:12px;color:#a9c2ff}
pre{font-family:Consolas,"Courier New",monospace;background:#0d1424;border:1px solid var(--border-soft);border-radius:10px;padding:12px 14px}

input.contents:
:root{
--color-bg:#f7f6f2;
--color-bg-alt:#ebe9e2;
--color-surface:#ffffff;
--color-text:#292825;
--color-text-muted:#6c6962;
--color-primary:#3f4b3e;
--color-secondary:#d8d2c3;
--color-accent:#7a2527;
--color-border:#cfccc3;
--color-border-strong:#aaa69b;
--color-hairline:#e4e1d9;
--color-strip:#dedbd2;
--muted:#6c6962;
--muted-2:#8a8577;
--font-display:"Segoe UI",Arial,sans-serif;
--font-body:"Segoe UI",Arial,sans-serif;
--font-mono:Consolas,"Courier New",monospace;
--fs-display:clamp(1.9rem,4vw,3rem);
--fs-h1:clamp(1.55rem,3.1vw,2.35rem);
--fs-h2:clamp(1.3rem,2.3vw,1.8rem);
--fs-h3:clamp(1.0625rem,1.5vw,1.25rem);
--fs-body-lg:1.0625rem;
--fs-body:1rem;
--fs-small:.8125rem;
--fs-caption:.6875rem;
--container-max:1200px;
--content-max:980px;
--reading-max:42rem;
--page-gutter:clamp(1rem,4vw,3rem);
--sidebar-w:268px;
--space-1:.25rem;
--space-2:.5rem;
--space-3:.75rem;
--space-4:1rem;
--space-5:1.5rem;
--space-6:2rem;
--space-7:3rem;
--space-8:4rem;
--radius:0;
--border-subtle:1px solid var(--color-border);
--border-hair:1px solid var(--color-hairline);
--ease-standard:ease-out;
--duration-fast:160ms;
--duration-normal:280ms;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{
background:var(--color-bg);
color:var(--color-text);
font-family:var(--font-body);
font-size:var(--fs-body);
line-height:1.6;
min-height:100vh;
-webkit-font-smoothing:antialiased;
}
a{color:inherit;text-decoration:none;text-underline-offset:.22em}
a:hover{text-decoration:underline}
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,.iv-st:focus-visible,.nav-link:focus-visible{
outline:3px solid var(--color-accent);
outline-offset:3px;
}
h1,h2,h3,h4{font-weight:500;letter-spacing:-.02em;line-height:1.25}
b,strong{font-weight:600}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:var(--color-bg-alt)}
::-webkit-scrollbar-thumb{background:var(--color-border-strong)}
::-webkit-scrollbar-thumb:hover{background:var(--color-text-muted)}
.skip-link{
position:fixed;
z-index:80;
top:1rem;
left:1rem;
padding:.7rem 1rem;
background:var(--color-text);
color:#fff;
font-size:var(--fs-small);
transform:translateY(-200%);
}
.skip-link:focus{transform:none}
.layout{display:flex;align-items:flex-start}
.sidebar{
position:fixed;
top:0;
left:0;
width:var(--sidebar-w);
height:100vh;
background:var(--color-bg-alt);
border-right:var(--border-subtle);
padding:var(--space-5) var(--space-4) var(--space-6);
overflow-y:auto;
z-index:50;
}
.brand{display:grid;grid-template-columns:2.25rem 1fr;gap:var(--space-3);align-items:center;padding-bottom:var(--space-4);border-bottom:var(--border-subtle);margin-bottom:var(--space-5)}
.brand-logo{
width:2.25rem;
height:2.25rem;
background:var(--color-text);
color:#fff;
display:flex;
align-items:center;
justify-content:center;
font-size:var(--fs-caption);
font-weight:700;
letter-spacing:.06em;
}
.brand-text b{display:block;font-size:var(--fs-small);font-weight:700;letter-spacing:.08em}
.brand-text span{display:block;font-size:var(--fs-caption);color:var(--color-text-muted);margin-top:2px}
.nav-group{margin-bottom:var(--space-5)}
.nav-title{font-size:var(--fs-caption);text-transform:uppercase;letter-spacing:.12em;color:var(--color-text-muted);font-weight:700;padding:0 var(--space-2) var(--space-2)}
.nav-link{
display:grid;
grid-template-columns:2rem 1fr;
gap:var(--space-3);
align-items:center;
min-height:2.5rem;
padding:var(--space-2) var(--space-2) var(--space-2) var(--space-3);
border-bottom:var(--border-hair);
font-size:var(--fs-small);
color:var(--color-text);
transition:background var(--duration-fast) var(--ease-standard),color var(--duration-fast) var(--ease-standard);
}
.nav-link:last-child{border-bottom:0}
.nav-link:hover{background:var(--color-surface);text-decoration:none}
.nav-link i{font-style:normal;font-size:var(--fs-caption);color:var(--color-text-muted);letter-spacing:.06em}
.nav-link.active{background:var(--color-surface);box-shadow:inset 3px 0 0 var(--color-primary);font-weight:600}
.nav-link.active i{color:var(--color-primary)}
.side-progress{border-top:var(--border-subtle);padding-top:var(--space-4);margin-top:var(--space-5)}
.sp-row{display:flex;justify-content:space-between;gap:var(--space-3);font-size:var(--fs-small);color:var(--color-text-muted);margin-bottom:var(--space-2)}
.sp-val{color:var(--color-primary);font-weight:700}
.main{flex:1;margin-left:var(--sidebar-w);padding:var(--space-6) var(--space-5) var(--space-9);max-width:var(--container-max)}
.topbar{
display:grid;
grid-template-columns:1fr auto;
gap:var(--space-5);
align-items:end;
background:var(--color-surface);
border-bottom:var(--border-subtle);
padding:0 0 var(--space-5);
}
.topbar h1{font-size:var(--fs-h1);font-weight:500;letter-spacing:-.035em;max-width:32ch}
.topbar h1 small{display:block;font-size:var(--fs-small);color:var(--color-text-muted);font-weight:400;letter-spacing:0;margin-top:var(--space-3);max-width:60ch}
.top-actions{display:flex;flex-wrap:wrap;gap:var(--space-2);align-items:center}
.btn{
display:inline-flex;
align-items:center;
justify-content:center;
min-height:2.75rem;
padding:var(--space-2) var(--space-4);
border:1px solid var(--color-border-strong);
background:var(--color-surface);
color:var(--color-text);
border-radius:0;
font-family:inherit;
font-size:var(--fs-small);
font-weight:600;
cursor:pointer;
transition:background var(--duration-fast) var(--ease-standard),color var(--duration-fast) var(--ease-standard),border-color var(--duration-fast) var(--ease-standard);
}
.btn:hover{background:var(--color-bg-alt);border-color:var(--color-text-muted)}
.btn-primary{background:var(--color-primary);border-color:var(--color-primary);color:#fff}
.btn-primary:hover{background:var(--color-accent);border-color:var(--color-accent)}
.btn-danger{background:transparent;border-color:var(--color-accent);color:var(--color-accent)}
.btn-danger:hover{background:var(--color-accent);border-color:var(--color-accent);color:#fff}
.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(11rem,1fr));gap:0;border-top:var(--border-subtle);margin-top:var(--space-6)}
.stat{padding:var(--space-4) var(--space-5) var(--space-4) 0;border-bottom:var(--border-subtle)}
.s-label{font-size:var(--fs-caption);text-transform:uppercase;letter-spacing:.12em;color:var(--color-text-muted);font-weight:700}
.s-value{font-size:var(--fs-h3);font-weight:600;letter-spacing:-.02em;margin-top:var(--space-2)}
.s-note{font-size:var(--fs-small);color:var(--color-text-muted);margin-top:2px}
.global-progress{border-top:var(--border-subtle);border-bottom:var(--border-subtle);padding:var(--space-5) 0;margin-top:var(--space-6)}
.gp-head{display:flex;justify-content:space-between;align-items:baseline;flex-wrap:wrap;gap:var(--space-3);margin-bottom:var(--space-2)}
.gp-head b{font-size:var(--fs-body-lg);font-weight:600}
.gp-head span{font-size:var(--fs-small);color:var(--color-text-muted)}
.bar{height:8px;background:var(--color-secondary);overflow:hidden}
.bar>span{display:block;height:100%;width:0;background:var(--color-primary);transition:width var(--duration-normal) var(--ease-standard)}
.bar.sm{height:5px}
.bar.bar-green>span{background:var(--color-primary)}
.bar.bar-yellow>span{background:var(--color-primary)}
.bar.bar-violet>span{background:var(--muted-2,#8a8577)}
.bar.bar-cyan>span{background:var(--color-accent)}
section{margin-top:var(--space-8);scroll-margin-top:var(--space-4)}
.sec-head{display:flex;gap:var(--space-4);align-items:flex-start;border-bottom:var(--border-subtle);padding-bottom:var(--space-3);margin-bottom:var(--space-5)}
.sec-num{
width:2.25rem;
height:2.25rem;
flex:0 0 2.25rem;
border:var(--border-subtle);
color:var(--color-primary);
display:flex;
align-items:center;
justify-content:center;
font-size:var(--fs-caption);
font-weight:700;
letter-spacing:.06em;
}
.sec-head h2{font-size:var(--fs-h2);font-weight:500;letter-spacing:-.025em}
.sec-head p{font-size:var(--fs-small);color:var(--color-text-muted);margin-top:var(--space-2);max-width:var(--reading-max)}
.grid{display:grid;gap:var(--space-6) var(--space-7)}
.g2{grid-template-columns:repeat(auto-fit,minmax(21rem,1fr))}
.g3{grid-template-columns:repeat(auto-fit,minmax(16rem,1fr))}
.g4{grid-template-columns:repeat(auto-fit,minmax(13rem,1fr))}
.card{background:transparent;border:0;border-top:var(--border-subtle);padding:var(--space-5) 0 0}
.card h3{font-size:var(--fs-h3);font-weight:600;letter-spacing:-.02em;margin-bottom:var(--space-3)}
.card h4{font-size:var(--fs-body);font-weight:600;margin:var(--space-5) 0 var(--space-2);padding-top:var(--space-3);border-top:var(--border-hair)}
.card p{color:var(--color-text-muted);font-size:var(--fs-body)}
.card>p+p{margin-top:var(--space-3)}
.card.tinted-blue,.card.tinted-violet,.card.tinted-green,.card.tinted-yellow{
background:var(--color-bg-alt);
border-top:0;
border-left:3px solid var(--color-primary);
padding:var(--space-5);
}
.card.tinted-violet{border-left-color:var(--muted-2,#8a8577)}
.card.tinted-yellow{border-left-color:var(--color-accent)}
.card.tinted-green{border-left-color:var(--color-primary)}
.pill{
display:inline-block;
padding:2px 8px;
border:1px solid var(--color-border-strong);
background:transparent;
color:var(--color-text-muted);
font-size:var(--fs-caption);
font-weight:700;
letter-spacing:.08em;
text-transform:uppercase;
white-space:nowrap;
}
.pill-blue,.pill-green{border-color:var(--color-primary);color:var(--color-primary)}
.pill-violet{border-color:var(--color-border-strong);color:var(--muted-2,#8a8577)}
.pill-gray{border-color:var(--color-border);color:var(--color-text-muted)}
.pill-yellow{border-color:var(--color-border-strong);color:var(--color-text)}
.pill-red{border-color:var(--color-accent);color:var(--color-accent)}
ul.clean{list-style:none}
ul.clean li{position:relative;padding-left:var(--space-4);margin:var(--space-2) 0;font-size:var(--fs-body);color:var(--color-text-muted)}
ul.clean li:before{content:"";position:absolute;left:2px;top:.55em;width:5px;height:5px;background:var(--color-border-strong)}
ul.clean li b{color:var(--color-text);font-weight:600}
ul.clean li code{color:var(--color-accent);background:var(--color-bg-alt);border-color:var(--color-hairline)}
ul.tick li:before{background:var(--color-primary)}
ul.warn li:before{background:var(--color-accent)}
.kv{display:flex;justify-content:space-between;gap:var(--space-4);font-size:var(--fs-small);padding:var(--space-2) 0;border-bottom:var(--border-hair)}
.kv:last-child{border-bottom:0}
.kv span:first-child{color:var(--color-text-muted)}
.kv span:last-child{color:var(--color-text);font-weight:600;text-align:right}
.check-list{border-top:var(--border-hair)}
.chk{
display:grid;
grid-template-columns:1.15rem 1fr;
gap:var(--space-3);
align-items:start;
padding:var(--space-3) var(--space-2);
border-bottom:var(--border-hair);
cursor:pointer;
transition:background var(--duration-fast) var(--ease-standard);
}
.chk:hover{background:var(--color-bg-alt)}
.chk input{position:absolute;opacity:0;width:0;height:0}
.chk .box{
width:1.15rem;
height:1.15rem;
margin-top:.15rem;
border:1px solid var(--color-border-strong);
background:var(--color-surface);
position:relative;
transition:background var(--duration-fast) var(--ease-standard),border-color var(--duration-fast) var(--ease-standard);
}
.chk .box:after{
content:"";
position:absolute;
left:.32rem;
top:.1rem;
width:.3rem;
height:.6rem;
border:solid #fff;
border-width:0 2px 2px 0;
transform:rotate(45deg) scale(0);
transition:transform var(--duration-fast) var(--ease-standard);
}
.chk input:checked+.box{background:var(--color-primary);border-color:var(--color-primary)}
.chk input:checked+.box:after{transform:rotate(45deg) scale(1)}
.chk input:checked~.chk-text{color:var(--color-text-muted)}
.chk-text{font-size:var(--fs-body);color:var(--color-text)}
.chk-text small{display:block;color:var(--color-text-muted);font-size:var(--fs-small);margin-top:var(--space-1)}
.chk.chk-core .box{border-color:var(--color-primary)}
.timeline{position:relative;padding-left:var(--space-5);border-top:var(--border-subtle)}
.timeline:before{content:"";position:absolute;left:5px;top:0;bottom:0;width:1px;background:var(--color-border)}
.tl-item{position:relative;padding:var(--space-4) 0;border-bottom:var(--border-hair)}
.tl-item:before{
content:"";
position:absolute;
left:calc(-1 * var(--space-5) + 1px);
top:1.15rem;
width:.65rem;
height:.65rem;
background:var(--color-surface);
border:2px solid var(--color-primary);
}
.tl-item.p2:before{border-color:var(--muted-2,#8a8577)}
.tl-item.p3:before{border-color:var(--color-accent)}
.tl-date{font-size:var(--fs-caption);color:var(--color-text-muted);font-weight:700;letter-spacing:.12em;text-transform:uppercase}
.tl-title{font-size:var(--fs-body-lg);font-weight:600;margin:var(--space-2) 0 var(--space-2)}
.tl-item p{color:var(--color-text-muted);font-size:var(--fs-body)}
.flow{display:flex;flex-direction:column;align-items:center;gap:0;padding:var(--space-3) 0}
.flow-node{
width:min(36rem,100%);
border:var(--border-subtle);
border-left:3px solid var(--color-border-strong);
background:var(--color-surface);
padding:var(--space-3) var(--space-4);
font-size:var(--fs-body);
font-weight:600;
}
.flow-node small{display:block;font-weight:400;font-size:var(--fs-small);color:var(--color-text-muted);margin-top:var(--space-1);line-height:1.55}
.flow-node.n-start{border-left-color:var(--color-secondary)}
.flow-node.n-core{border-left-color:var(--color-primary)}
.flow-node.n-data{border-left-color:var(--color-primary)}
.flow-node.n-sec{border-left-color:var(--color-accent)}
.flow-node.n-arch{border-left-color:var(--muted-2,#8a8577)}
.flow-node.n-fe{border-left-color:var(--color-border-strong)}
.flow-node.n-final{background:var(--color-text);border-color:var(--color-text);border-left-color:var(--color-accent);color:#fff}
.flow-node.n-final small{color:#cfccc3}
.flow-node.n-goal{background:var(--color-primary);border-color:var(--color-primary);border-left-color:var(--color-secondary);color:#fff}
.flow-node.n-goal small{color:#d8d2c3}
.flow-arrow{width:1px;height:1.5rem;background:var(--color-border-strong);position:relative}
.flow-arrow:after{
content:"";
position:absolute;
left:50%;
transform:translateX(-50%);
bottom:-1px;
border-left:5px solid transparent;
border-right:5px solid transparent;
border-top:7px solid var(--color-border-strong);
}
.flow-branch{display:flex;gap:var(--space-3);flex-wrap:wrap;justify-content:center;width:100%}
.arch{display:flex;flex-direction:column;gap:0;align-items:center}
.arch-layer{
width:min(42rem,100%);
border:var(--border-subtle);
border-left:3px solid var(--color-border-strong);
background:var(--color-surface);
padding:var(--space-3) var(--space-4);
}
.arch-layer b{font-size:var(--fs-body);font-weight:600}
.arch-layer span{display:block;font-size:var(--fs-small);color:var(--color-text-muted);margin-top:var(--space-1);line-height:1.55}
.arch-layer.l-client{border-left-color:var(--color-secondary)}
.arch-layer.l-api{border-left-color:var(--color-primary)}
.arch-layer.l-app{border-left-color:var(--muted-2,#8a8577)}
.arch-layer.l-domain{border-left-color:var(--color-accent)}
.arch-layer.l-infra{border-left-color:var(--color-text-muted)}
.arch-layer.l-db{background:var(--color-bg-alt);border-left-color:var(--color-text)}
.arch-down{height:1.25rem;width:1px;background:var(--color-border-strong);position:relative}
.arch-down:after{
content:"";
position:absolute;
left:50%;
transform:translateX(-50%);
bottom:-1px;
border-left:5px solid transparent;
border-right:5px solid transparent;
border-top:7px solid var(--color-border-strong);
}
.arch-cols{display:flex;gap:var(--space-4);flex-wrap:wrap;justify-content:center;width:100%}
.arch-col{flex:1 1 13rem;min-width:12rem;border:var(--border-subtle);background:var(--color-surface);padding:var(--space-4)}
.arch-col h5{font-size:var(--fs-small);font-weight:700;letter-spacing:.04em;margin-bottom:var(--space-2)}
.arch-col ul{list-style:none}
.arch-col li{font-size:var(--fs-small);color:var(--color-text-muted);padding:2px 0 2px var(--space-3);position:relative}
.arch-col li:before{content:"";position:absolute;left:0;top:.6em;width:4px;height:4px;background:var(--color-border-strong)}
table{width:100%;border-collapse:collapse;font-size:var(--fs-small)}
th,td{padding:var(--space-3) var(--space-3);text-align:left;border-bottom:var(--border-hair);vertical-align:top}
th{font-size:var(--fs-caption);text-transform:uppercase;letter-spacing:.1em;color:var(--color-text-muted);background:var(--color-bg-alt);font-weight:700;border-bottom:var(--border-subtle)}
tbody tr:hover{background:var(--color-bg-alt)}
.tbl-wrap{overflow-x:auto;border:var(--border-subtle);background:var(--color-surface)}
code{
font-family:var(--font-mono);
font-size:.875em;
color:var(--color-accent);
background:var(--color-bg-alt);
border:1px solid var(--color-hairline);
padding:1px 4px;
}
pre{font-family:var(--font-mono);background:var(--color-bg-alt);border:var(--border-subtle);padding:var(--space-4);overflow-x:auto;font-size:var(--fs-small);line-height:1.7;color:var(--color-text)}
.lvl{
display:inline-block;
min-width:7rem;
padding:2px 8px;
border:1px solid var(--color-border);
background:transparent;
color:var(--color-text-muted);
font-size:var(--fs-caption);
font-weight:700;
letter-spacing:.06em;
text-transform:uppercase;
text-align:center;
}
.lvl-1{border-color:var(--color-border-strong);color:var(--color-text)}
.lvl-2{border-color:var(--color-primary);color:var(--color-primary)}
.lvl-3{background:var(--color-primary);border-color:var(--color-primary);color:#fff}
.week-card{background:transparent;border:0;border-bottom:var(--border-subtle);overflow:hidden}
.week-card:first-child{border-top:var(--border-subtle)}
.wc-head{
display:grid;
grid-template-columns:1fr auto;
gap:var(--space-4);
align-items:center;
padding:var(--space-4) var(--space-2);
background:transparent;
border:0;
cursor:pointer;
transition:background var(--duration-fast) var(--ease-standard);
}
.wc-head:hover{background:var(--color-bg-alt)}
.wc-head b{font-size:var(--fs-body);font-weight:600}
.wc-head span{font-size:var(--fs-small);color:var(--color-text-muted)}
.week-card .wc-body{padding:0 var(--space-2) var(--space-5);display:none}
.week-card.open .wc-body{display:block}
.en-line{font-size:var(--fs-body);color:var(--color-text);padding:var(--space-3) 0 var(--space-3) var(--space-5);border-bottom:var(--border-hair);position:relative}
.en-line:last-child{border-bottom:0}
.en-line:before{content:"“";position:absolute;left:0;top:.6rem;color:var(--color-accent);font-size:1.6rem;line-height:1;font-weight:700}
.en-line i{display:block;color:var(--color-text-muted);font-style:normal;font-size:var(--fs-small);margin-top:var(--space-1)}
.iv-item{
display:grid;
grid-template-columns:2.5rem 1fr auto;
gap:var(--space-4);
align-items:start;
padding:var(--space-4) var(--space-2);
border-bottom:var(--border-hair);
background:transparent;
}
.iv-item:hover{background:var(--color-bg-alt)}
.iv-idx{font-family:var(--font-mono);font-size:var(--fs-small);color:var(--color-text-muted);padding-top:3px}
.iv-q{font-size:var(--fs-body);line-height:1.6}
.iv-q small{display:block;color:var(--color-text-muted);font-size:var(--fs-small);margin-top:var(--space-2)}
.iv-states{display:flex;gap:var(--space-2);flex-wrap:wrap;justify-content:flex-end;max-width:22rem}
.iv-st{
padding:4px 8px;
border:1px solid var(--color-border);
background:transparent;
color:var(--color-text-muted);
font-size:var(--fs-caption);
font-weight:600;
cursor:pointer;
user-select:none;
white-space:nowrap;
transition:background var(--duration-fast) var(--ease-standard),color var(--duration-fast) var(--ease-standard),border-color var(--duration-fast) var(--ease-standard);
}
.iv-st:hover{border-color:var(--color-text-muted);color:var(--color-text)}
.iv-st.on.s1{background:var(--color-secondary);border-color:var(--color-border-strong);color:var(--color-text)}
.iv-st.on.s2{background:var(--color-primary);border-color:var(--color-primary);color:#fff}
.iv-st.on.s3{background:var(--color-accent);border-color:var(--color-accent);color:#fff}
.iv-group{padding-top:var(--space-5);margin-bottom:var(--space-5);border-top:var(--border-subtle)}
.iv-group-head{display:flex;align-items:baseline;justify-content:space-between;gap:var(--space-4);flex-wrap:wrap;margin-bottom:var(--space-3)}
.iv-group-head h3{font-size:var(--fs-h3);font-weight:600}
.iv-group-head .mini{font-size:var(--fs-small);color:var(--color-text-muted)}
.callout{
display:grid;
grid-template-columns:7rem 1fr;
gap:var(--space-4);
align-items:start;
background:var(--color-bg-alt);
border-left:3px solid var(--color-primary);
padding:var(--space-4);
font-size:var(--fs-body);
color:var(--color-text);
}
.callout .c-mark{font-size:var(--fs-caption);font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--color-text-muted);padding-top:2px}
.callout b{color:var(--color-text)}
.callout.warn{border-left-color:var(--color-accent)}
.callout.info{border-left-color:var(--color-primary)}
.callout.ok{border-left-color:var(--color-border-strong)}
.day-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(15rem,1fr));gap:var(--space-6) var(--space-7)}
.day-card{border-top:var(--border-subtle);padding:var(--space-4) 0 0}
.dc-head{display:flex;justify-content:space-between;align-items:baseline;gap:var(--space-3);margin-bottom:var(--space-3)}
.dc-head b{font-size:var(--fs-body);font-weight:600}
.dc-head span{font-size:var(--fs-caption);color:var(--color-text-muted)}
.dc-line{display:flex;justify-content:space-between;gap:var(--space-3);font-size:var(--fs-small);padding:var(--space-2) 0;color:var(--color-text-muted);border-bottom:var(--border-hair)}
.dc-line:last-of-type{border-bottom:0}
.dc-line b{color:var(--color-text);font-weight:600}
.day-card p{margin-top:var(--space-3)!important;font-size:var(--fs-small)!important;color:var(--color-text-muted)}
.phase-head{display:grid;grid-template-columns:1fr auto;gap:var(--space-5);align-items:center}
.phase-badge{display:grid;grid-template-columns:2.75rem 1fr;gap:var(--space-4);align-items:center}
.pb-num{
width:2.75rem;
height:2.75rem;
display:flex;
align-items:center;
justify-content:center;
font-size:var(--fs-body-lg);
font-weight:700;
color:#fff;
background:var(--color-primary);
}
.pb-num.p2{background:var(--muted-2,#8a8577)}
.pb-num.p3{background:var(--color-accent)}
.phase-badge b{display:block;font-size:var(--fs-body-lg);font-weight:600}
.phase-badge span{font-size:var(--fs-small);color:var(--color-text-muted);display:block;margin-top:var(--space-1)}
.toast{
position:fixed;
right:var(--space-5);
bottom:var(--space-5);
max-width:24rem;
padding:var(--space-3) var(--space-4);
background:var(--color-text);
color:#fff;
font-size:var(--fs-small);
opacity:0;
transform:translateY(8px);
transition:opacity var(--duration-normal) var(--ease-standard),transform var(--duration-normal) var(--ease-standard);
pointer-events:none;
z-index:200;
}
.toast.show{opacity:1;transform:translateY(0)}
.mobile-bar{display:none}
.footer{
margin-top:var(--space-9);
padding-top:var(--space-5);
border-top:var(--border-subtle);
color:var(--color-text-muted);
font-size:var(--fs-small);
line-height:1.8;
}
.footer b{color:var(--color-text)}
.footer a{color:var(--color-primary);text-decoration:underline}
.to-top{display:inline-block;margin-top:var(--space-3);font-weight:600}
@media(max-width:1024px){
.sidebar{transform:translateX(-100%);transition:transform var(--duration-normal) var(--ease-standard)}
.sidebar.open{transform:translateX(0);box-shadow:0 0 0 100vmax rgba(31,30,27,.34)}
.main{margin-left:0;padding:var(--space-5) var(--space-4) var(--space-8);max-width:none}
.mobile-bar{
display:grid;
grid-template-columns:1fr auto auto;
gap:var(--space-3);
align-items:center;
position:sticky;
top:0;
z-index:60;
padding:var(--space-3) var(--space-4);
background:var(--color-surface);
border-bottom:var(--border-subtle);
}
.mobile-bar b{font-size:var(--fs-small);font-weight:700;letter-spacing:.08em}
.mobile-bar .mb-progress{font-size:var(--fs-small);color:var(--color-primary);font-weight:700}
.topbar{grid-template-columns:1fr}
.phase-head{grid-template-columns:1fr}
.flow-node,.arch-layer{width:100%}
}
@media(max-width:760px){
.iv-item{grid-template-columns:2rem 1fr}
.iv-states{grid-column:2;justify-content:flex-start;max-width:none}
.callout{grid-template-columns:1fr;gap:var(--space-2)}
.topbar h1{max-width:none}
.grid{gap:var(--space-5) 0}
}
@media(prefers-reduced-motion:reduce){
html{scroll-behavior:auto}
*,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important}
}
@media print{
.sidebar,.top-actions,.mobile-bar,.toast,.skip-link{display:none!important}
body{background:#fff;color:#111}
.main{margin:0;padding:0;max-width:none}
.card,.stat,.tbl-wrap,.week-card,.day-card,.topbar,.global-progress{background:#fff!important;border-color:#bbb!important;box-shadow:none!important;break-inside:avoid}
.bar{background:#e5e5e5!important}
.bar>span{background:#3f4b3e!important}
.pill,.lvl,.iv-st{border-color:#999!important;color:#111!important}
.lvl-3,.iv-st.on.s2,.iv-st.on.s3{background:#eee!important;color:#111!important}
.flow-node,.arch-layer{background:#fff!important;color:#111!important;border-color:#999!important}
.flow-node.n-final,.flow-node.n-goal{background:#eee!important}
.week-card .wc-body{display:block!important}
.callout{background:#f2f2f2!important}
section{page-break-inside:avoid}
a[href^="#"]{text-decoration:none}
}

