:root{
--color-bg:#ffffff;
--color-bg-alt:#f2f4f0;
--color-surface:#ffffff;
--color-text:#292b2a;
--color-text-muted:#727773;
--color-primary:#00664f;
--color-secondary:#064a3d;
--color-accent:#00a651;
--color-border:#d6dbd7;
--color-border-strong:#a9b2ac;
--color-dark:#222222;
--color-overlay:rgba(10,25,20,.5);
--color-focus:#064a3d;
--color-focus-light:#f5d547;
--color-link-hover:#65d4a3;
--font-display:Arial,"Helvetica Neue",sans-serif;
--font-body:Arial,"Helvetica Neue",sans-serif;
--font-mono:Consolas,"Courier New",monospace;
--fs-display:clamp(2rem,4.4vw,3.5rem);
--fs-h1:clamp(1.75rem,3.4vw,2.9rem);
--fs-h2:clamp(1.4rem,2.4vw,2rem);
--fs-h3:clamp(1.05rem,1.5vw,1.35rem);
--fs-body-lg:clamp(1.05rem,1.4vw,1.2rem);
--fs-body:1rem;
--fs-small:.8rem;
--fs-caption:.72rem;
--container-max:88rem;
--content-max:46rem;
--reading-max:46rem;
--page-gutter:clamp(1rem,4vw,4rem);
--sidebar-w:17.5rem;
--space-1:.25rem;
--space-2:.5rem;
--space-3:.75rem;
--space-4:1rem;
--space-5:1.5rem;
--space-6:2rem;
--space-7:3rem;
--space-8:4.5rem;
--space-9:7rem;
--radius-sm:.1rem;
--radius-md:.25rem;
--border-subtle:1px solid var(--color-border);
--ease-standard:cubic-bezier(.2,.8,.2,1);
--duration-fast:180ms;
--duration-normal:320ms;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{
background:var(--color-bg);
color:var(--color-text);
font-family:var(--font-body);
font-size:var(--fs-body);
line-height:1.55;
min-height:100vh;
overflow-x:hidden;
}
h1,h2,h3,h4{font-weight:700;line-height:1.2;letter-spacing:-.02em}
a{color:inherit;text-decoration:none}
a:hover{color:var(--color-primary)}
:focus-visible{outline:3px solid var(--color-focus);outline-offset:4px}
:focus:not(:focus-visible){outline:none}
b,strong{font-weight:700}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:var(--color-bg-alt)}
::-webkit-scrollbar-thumb{background:var(--color-border-strong)}
::-webkit-scrollbar-thumb:hover{background:var(--color-text-muted)}
.skip-link{position:fixed;top:.5rem;left:.5rem;z-index:120;background:var(--color-surface);padding:.7rem 1rem;font-size:var(--fs-small);font-weight:700;transform:translateY(-150%)}
.skip-link:focus{transform:none}
.layout{display:flex;align-items:flex-start}
.sidebar{
position:fixed;
top:0;
left:0;
width:var(--sidebar-w);
height:100vh;
background:var(--color-primary);
color:#fff;
padding:var(--space-5) var(--space-4) var(--space-6);
overflow-y:auto;
z-index:50;
}
.sidebar::-webkit-scrollbar-track{background:var(--color-secondary)}
.sidebar::-webkit-scrollbar-thumb{background:#3f8a75}
.sidebar :focus-visible{outline:3px solid var(--color-focus-light);outline-offset:3px}
.brand{display:grid;grid-template-columns:2.6rem 1fr;gap:var(--space-3);align-items:center;padding-bottom:var(--space-4);border-bottom:1px solid rgba(255,255,255,.35);margin-bottom:var(--space-5)}
.brand-logo{
width:2.6rem;
height:2.6rem;
border:1px solid rgba(255,255,255,.7);
border-radius:50%;
display:grid;
place-items:center;
font-size:.8rem;
font-weight:800;
letter-spacing:.04em;
}
.brand-text b{display:block;font-size:var(--fs-small);font-weight:800;letter-spacing:.1em;line-height:1.25}
.brand-text span{display:block;font-size:var(--fs-caption);color:rgba(255,255,255,.78);margin-top:2px}
.nav-group{margin-bottom:var(--space-5)}
.nav-title{
font-size:var(--fs-caption);
text-transform:uppercase;
letter-spacing:.18em;
font-weight:800;
color:var(--color-link-hover);
padding:0 var(--space-2) var(--space-2);
}
.nav-link{
display:grid;
grid-template-columns:1.85rem 1fr;
gap:var(--space-3);
align-items:center;
min-height:2.75rem;
padding:var(--space-2) var(--space-2) var(--space-2) 0;
border-bottom:1px solid rgba(255,255,255,.18);
font-size:var(--fs-small);
font-weight:700;
color:rgba(255,255,255,.9);
transition:background var(--duration-fast) var(--ease-standard),color var(--duration-fast) var(--ease-standard);
}
