/* ============================================================
   ROADMAP .NET 2027 — engine dùng chung cho mọi trang
   Yêu cầu: biến CHECK_ITEMS và các mảng dữ liệu WEEKS,
   EN_WEEKS, IV_DATA được định nghĩa trước file này.
   ============================================================ */
(function(){
"use strict";
var LS_PROGRESS="rd2027.progress.v1";
var LS_INTERVIEW="rd2027.interview.v1";
var LS_DAILY="rd2027.daily.v1";
var LABELS=["Chưa học","Đã học","Có thể giải thích","Có thể trả lời bằng tiếng Anh"];
var storageOk=(function(){
try{
localStorage.setItem("rd2027.probe","1");
localStorage.removeItem("rd2027.probe");
return true;
}catch(e){
return false;
}
})();
var memStore={};
function byId(id){return document.getElementById(id);}
function setHTML(id,text){var el=byId(id);if(el){el.textContent=text;}}
function setWidth(id,pct){var el=byId(id);if(el){el.style.width=pct+"%";}}
function readRaw(key){
try{
return localStorage.getItem(key);
}catch(e){
return Object.prototype.hasOwnProperty.call(memStore,key)?memStore[key]:null;
}
}
function writeRaw(key,val){
try{
localStorage.setItem(key,val);
}catch(e){
memStore[key]=val;
}
}
function readObj(key,def){
var raw=readRaw(key);
if(!raw){return def;}
try{
var v=JSON.parse(raw);
if(v===null||typeof v!=="object"){return def;}
return v;
}catch(e){
return def;
}
}
function writeObj(key,val){writeRaw(key,JSON.stringify(val));}
function todayKey(){
var d=new Date();
var m=d.getMonth()+1;
var day=d.getDate();
return d.getFullYear()+"-"+((m<10)?"0":"")+m+"-"+((day<10)?"0":"")+day;
}
var state={
progress:readObj(LS_PROGRESS,{}),
interview:readObj(LS_INTERVIEW,{}),
daily:readObj(LS_DAILY,null)
};
function saveProgress(){writeObj(LS_PROGRESS,state.progress);}
function saveInterview(){writeObj(LS_INTERVIEW,state.interview);}
function saveDaily(){writeObj(LS_DAILY,state.daily);}
function phaseOf(id){
var i=id.indexOf("_");
return (i<0)?id:id.substring(0,i);
}
function phaseStats(phase){
var total=0;
var done=0;
for(var i=0;i<CHECK_ITEMS.length;i++){
if(phaseOf(CHECK_ITEMS[i])!==phase){continue;}
total++;
if(state.progress[CHECK_ITEMS[i]]){done++;}
}
var pct=(total===0)?0:Math.round(done*100/total);
return{total:total,done:done,pct:pct};
}
function ivStats(){
var total=0;
var sum=0;
var learned=0;
var explain=0;
var eng=0;
for(var c=0;c<IV_DATA.length;c++){total+=IV_DATA[c].items.length;}
for(var i=1;i<=total;i++){
var v=state.interview["iv_"+i]||0;
sum+=v;
if(v>=1){learned++;}
if(v>=2){explain++;}
if(v===3){eng++;}
}
var pct=(total===0)?0:Math.round(sum*100/(total*3));
return{total:total,sum:sum,learned:learned,explain:explain,eng:eng,pct:pct};
}
function toast(msg){
var t=byId("toast");
if(!t){return;}
t.textContent=msg;
t.classList.add("show");
if(t.__timer){clearTimeout(t.__timer);}
t.__timer=setTimeout(function(){t.classList.remove("show");},1900);
}
function updateAll(){
var p1=phaseStats("p1");
var p2=phaseStats("p2");
var p3=phaseStats("p3");
var prj=phaseStats("prj");
var wk=phaseStats("wk");
var iv=ivStats();
setWidth("p1Bar",p1.pct);
setHTML("p1Text",p1.pct+"%");
setWidth("p2Bar",p2.pct);
setHTML("p2Text",p2.pct+"%");
setWidth("p3Bar",p3.pct);
setHTML("p3Text",p3.pct+"%");
setWidth("ivBar",iv.pct);
setHTML("ivText",iv.pct+"%");
setWidth("p1PhaseBar",p1.pct);
setHTML("p1PhaseText",p1.done+"/"+p1.total+" — "+p1.pct+"%");
setWidth("p2PhaseBar",p2.pct);
setHTML("p2PhaseText",p2.done+"/"+p2.total+" — "+p2.pct+"%");
setWidth("p3PhaseBar",p3.pct);
setHTML("p3PhaseText",p3.done+"/"+p3.total+" — "+p3.pct+"%");
setWidth("prjPhaseBar",prj.pct);
setHTML("prjPhaseText",prj.done+"/"+prj.total+" — "+prj.pct+"%");
setWidth("wkPhaseBar",wk.pct);
setHTML("wkPhaseText",wk.done+"/"+wk.total+" — "+wk.pct+"%");
setWidth("tmP1",p1.pct);
setHTML("tmP1Text",p1.pct+"%");
setWidth("tmP2",p2.pct);
setHTML("tmP2Text",p2.pct+"%");
setWidth("tmP3",p3.pct);
setHTML("tmP3Text",p3.pct+"%");
setWidth("tmPrj",prj.pct);
setHTML("tmPrjText",prj.pct+"%");
setWidth("tmIv",iv.pct);
setHTML("tmIvText",iv.pct+"%");
var chkTotal=0;
var chkDone=0;
var phases=["p1","p2","p3","prj","wk"];
for(var i=0;i<phases.length;i++){
var s=phaseStats(phases[i]);
chkTotal+=s.total;
chkDone+=s.done;
}
var grandTotal=chkTotal+iv.total;
var grandDone=chkDone+(iv.sum/3);
var gpct=(grandTotal===0)?0:Math.round(grandDone*100/grandTotal);
setWidth("gpBar",gpct);
setHTML("gpText",chkDone+" / "+chkTotal+" mục checklist — "+gpct+"%");
setWidth("sideBar",gpct);
setHTML("sideProgress",gpct+"%");
setHTML("sideCount",chkDone+"/"+chkTotal);
setHTML("mbProgress",gpct+"%");
setHTML("ivLearned",iv.learned);
setHTML("ivExplain",iv.explain);
setHTML("ivEnglish",iv.eng);
setHTML("ivScore",iv.pct+"%");
var heads=document.querySelectorAll("[data-ivhead]");
var startIdx=1;
for(var c=0;c<IV_DATA.length;c++){
var cnt=IV_DATA[c].items.length;
var done=0;
for(var k=startIdx;k<startIdx+cnt;k++){
if((state.interview["iv_"+k]||0)>=2){done++;}
}
if(heads[c]){heads[c].textContent=done+" / "+cnt+" cần đạt mức giải thích";}
startIdx+=cnt;
}
}
function toggleWeek(head){
var card=head.parentNode;
if(!card){return;}
card.classList.toggle("open");
var isOpen=card.classList.contains("open");
head.setAttribute("aria-expanded",isOpen?"true":"false");
}
function toggleWeekKey(ev,head){
if(ev.key!=="Enter"&&ev.key!==" "){return;}
ev.preventDefault();
toggleWeek(head);
}
function setIvState(el){
var wrap=el.parentNode;
if(!wrap){return;}
var key=wrap.getAttribute("data-ivkey");
var val=parseInt(el.getAttribute("data-s"),10);
var cur=state.interview[key]||0;
state.interview[key]=(cur===val)?0:val;
saveInterview();
applyIvState();
updateAll();
}
function applyIvState(){
var nodes=document.querySelectorAll(".iv-states");
for(var i=0;i<nodes.length;i++){
var key=nodes[i].getAttribute("data-ivkey");
var val=state.interview[key]||0;
var opts=nodes[i].getElementsByClassName("iv-st");
for(var j=0;j<opts.length;j++){
var isOn=(parseInt(opts[j].getAttribute("data-s"),10)===val)&&val>0;
opts[j].className=isOn?("iv-st s"+val+" on"):("iv-st s"+j);
opts[j].setAttribute("aria-pressed",isOn?"true":"false");
}
}
}
function buildWeeks(){
var box=byId("weekContainer");
if(!box){return;}
var html="";
for(var i=0;i<WEEKS.length;i++){
var w=WEEKS[i];
var cls=(w.ph==="P1")?"pill-yellow":((w.ph==="P2")?"pill-violet":"pill-green");
html+='<div class="week-card" data-wk="'+w.w+'">';
html+='<div class="wc-head" role="button" tabindex="0" aria-expanded="false" onclick="window.__toggleWeek(this)" onkeydown="window.__toggleWeekKey(event,this)"><span><b>Tuần '+w.w+' — '+w.t+'</b><br/><span>'+w.d+'</span></span><span><span class="pill '+cls+'">'+w.ph+'</span> <span class="wc-caret">▾</span></span></div>';
html+='<div class="wc-body">';
html+='<p><b>Trọng tâm:</b> '+w.focus+'</p>';
html+='<h4>Kiến thức / kỹ thuật</h4><ul class="clean">';
for(var j=0;j<w.net.length;j++){html+='<li>'+w.net[j]+'</li>';}
html+='</ul>';
html+='<h4>Project / thực hành</h4><p>'+w.prj+'</p>';
html+='<h4>English chủ đề tuần</h4><p>'+w.en+'</p>';
html+='<h4>Deliverable cuối tuần</h4><p><span class="pill pill-green">'+w.deliver+'</span></p>';
html+='</div></div>';
}
box.innerHTML=html;
}
function buildEnglish(){
var box=byId("enContainer");
if(!box){return;}
var html="";
for(var i=0;i<EN_WEEKS.length;i++){
var w=EN_WEEKS[i];
html+='<div class="week-card" data-en="'+w.w+'">';
html+='<div class="wc-head" role="button" tabindex="0" aria-expanded="false" onclick="window.__toggleWeek(this)" onkeydown="window.__toggleWeekKey(event,this)"><span><b>Week '+w.w+' — '+w.t+'</b><br/><span>'+w.d+'</span></span><span>'+w.lines.length+' câu <span class="wc-caret">▾</span></span></div>';
html+='<div class="wc-body">';
for(var j=0;j<w.lines.length;j++){
html+='<div class="en-line">'+w.lines[j].en+'<i>'+w.lines[j].vi+'</i></div>';
}
html+='</div></div>';
}
box.innerHTML=html;
}
function buildInterview(){
var box=byId("ivContainer");
if(!box){return;}
var html="";
var idx=0;
for(var c=0;c<IV_DATA.length;c++){
var g=IV_DATA[c];
html+='<div class="iv-group">';
html+='<div class="iv-group-head"><h3>'+g.cat+' <span class="mini">('+g.items.length+' câu)</span></h3><span class="mini" data-ivhead="'+c+'">0 / '+g.items.length+'</span></div>';
for(var k=0;k<g.items.length;k++){
idx++;
var key="iv_"+idx;
html+='<div class="iv-item">';
html+='<div class="iv-idx">'+((idx<10)?"0":"")+idx+'</div>';
html+='<div class="iv-q">'+g.items[k].q+'<small>Gợi ý: '+g.items[k].h+'</small></div>';
html+='<div class="iv-states" data-ivkey="'+key+'" data-ivcat="'+c+'">';
for(var s=0;s<4;s++){
html+='<button type="button" class="iv-st s'+s+'" data-s="'+s+'" title="'+LABELS[s]+'" aria-pressed="false" onclick="window.__setIvState(this)">'+LABELS[s]+'</button>';
}
html+='</div></div>';
}
html+='</div>';
}
box.innerHTML=html;
applyIvState();
}
function resetDailyIfNewDay(){
if(!state.daily||state.daily.date!==todayKey()){
state.daily={date:todayKey(),items:{}};
saveDaily();
return;
}
}
function bindCheckboxes(){
var all=document.querySelectorAll(".chk input[type=checkbox]");
for(var i=0;i<all.length;i++){
var cb=all[i];
var isDaily=cb.getAttribute("data-daily")==="1";
if(isDaily){
var items=(state.daily&&state.daily.date===todayKey())?state.daily.items:{};
cb.checked=!!items[cb.id];
}else{
cb.checked=!!state.progress[cb.id];
}
cb.onchange=(function(box,flag){
return function(){
if(flag){
state.daily.items[box.id]=box.checked;
saveDaily();
}else{
if(box.checked){state.progress[box.id]=1;}else{delete state.progress[box.id];}
saveProgress();
}
var row=box.parentNode;
if(row&&row.setAttribute&&box.checked){row.setAttribute("data-done","1");}
updateAll();
};
})(cb,isDaily);
}
}
function expandAllWeeks(){
try{
var cards=document.querySelectorAll(".week-card");
if(!cards.length){toast("Trang này không có weekly card");return;}
var anyClosed=false;
for(var i=0;i<cards.length;i++){
if(!cards[i].classList.contains("open")){anyClosed=true;break;}
}
for(var j=0;j<cards.length;j++){
var head=cards[j].getElementsByClassName("wc-head")[0];
if(anyClosed){cards[j].classList.add("open");}else{cards[j].classList.remove("open");}
if(head){head.setAttribute("aria-expanded",anyClosed?"true":"false");}
}
toast(anyClosed?"Đã mở tất cả weekly cards":"Đã thu gọn tất cả weekly cards");
}catch(e){
toast("Không mở được danh sách tuần");
}
}
function resetProgress(){
var ok=window.confirm("Xoá toàn bộ tiến độ đã lưu (checklist các phase, 100 câu hỏi, daily)?\nHành động này không thể hoàn tác.");
if(!ok){return;}
state.progress={};
state.interview={};
state.daily={date:todayKey(),items:{}};
try{
localStorage.removeItem(LS_PROGRESS);
localStorage.removeItem(LS_INTERVIEW);
localStorage.removeItem(LS_DAILY);
}catch(e){
memStore={};
}
var boxes=document.querySelectorAll(".chk input[type=checkbox]");
for(var i=0;i<boxes.length;i++){boxes[i].checked=false;}
applyIvState();
updateAll();
toast("Đã xoá toàn bộ tiến độ. Bắt đầu lại từ 01/10/2026!");
}
function toggleSidebar(){
var s=byId("sidebar");
if(!s){return;}
s.classList.toggle("open");
var open=s.classList.contains("open");
var btn=document.querySelector(".mobile-bar .btn");
if(btn){btn.setAttribute("aria-expanded",open?"true":"false");}
}
function markActiveNav(){
try{
var page=document.body.getAttribute("data-page");
if(!page){return;}
var links=document.querySelectorAll(".nav-link");
for(var i=0;i<links.length;i++){
if(links[i].getAttribute("data-nav")===page){
links[i].classList.add("active");
links[i].setAttribute("aria-current","page");
}
}
}catch(e){}
}
function storageNotice(){
if(storageOk){return;}
var box=byId("storageWarn");
if(box){box.hidden=false;}
}
function init(){
markActiveNav();
resetDailyIfNewDay();
buildWeeks();
buildEnglish();
buildInterview();
bindCheckboxes();
updateAll();
storageNotice();
}
window.__toggleWeek=toggleWeek;
window.__toggleWeekKey=toggleWeekKey;
window.__setIvState=setIvState;
window.toggleSidebar=toggleSidebar;
window.expandAllWeeks=expandAllWeeks;
window.resetProgress=resetProgress;
window.addEventListener("storage",function(ev){
if(!ev.key){return;}
if(ev.key===LS_PROGRESS||ev.key===LS_INTERVIEW||ev.key===LS_DAILY){
state.progress=readObj(LS_PROGRESS,{});
state.interview=readObj(LS_INTERVIEW,{});
state.daily=readObj(LS_DAILY,null);
resetDailyIfNewDay();
bindCheckboxes();
updateAll();
}
});
if(document.readyState==="loading"){
document.addEventListener("DOMContentLoaded",init);
}else{
init();
}
})();

