var fs = require("fs");
var path = require("path");
var ROOT = "g:/1.Lộ trình/code";
var SRC = path.join(ROOT, "roadmap_dotnet_2027.html");
var log = [];

var src = fs.readFileSync(SRC, "utf8").replace(/\r\n/g, "\n");

/* ---------- 1. CSS ---------- */
var cssStart = src.indexOf("<style>") + "<style>".length;
var cssEnd = src.indexOf("</style>");
var baseCss = src.slice(cssStart, cssEnd).trim();
var extraCss = fs.readFileSync(path.join(ROOT, "assets/_extra.css"), "utf8").replace(/\r\n/g, "\n").trim();
