});

var anch = [];
files.forEach(function (f) {
    var h = fs.readFileSync(f, "utf8");
    (h.match(/href="#[A-Za-z0-9]+"/g) || []).forEach(function (a) { anch.push(f + ": " + a); });
});
console.log("--- anchor con lai ---");
console.log(anch.length ? anch.join("\n") : "khong con");

console.log("--- section ids trong tung trang ---");
files.sort().forEach(function (f) {
