var fs = require("fs");
var path = require("path");
var ROOT = "g:/1.Lộ trình/code";
/* Nguồn dữ liệu: bản 1 trang gốc giữ trong _backup. Đích build: các file html trong ROOT. */
var SRC = path.join(ROOT, "_backup/roadmap_dotnet_2027_1trang.html");
var log = [];

var src = fs.readFileSync(SRC, "utf8").replace(/\r\n/g, "\n");
if (src.indexOf("var WEEKS = [") < 0) { throw new Error("file nguon " + SRC + " khong phai ban roadmap 1 trang goc"); }

/* ---------- 1. CSS ---------- */
var cssStart = src.indexOf("<style>") + "<style>".length;
var cssEnd = src.indexOf("</style>");
var baseCss = src.slice(cssStart, cssEnd).trim();
var extraCss = fs.readFileSync(path.join(ROOT, "_build/extra.css"), "utf8").replace(/\r\n/g, "\n").trim();
var fullCss = "/* Roadmap .NET 2027 - stylesheet dung chung cho moi trang */\n" + baseCss + "\n" + extraCss + "\n";
fs.writeFileSync(path.join(ROOT, "assets/roadmap.css"), fullCss, "utf8");
log.push("assets/roadmap.css: " + fullCss.split("\n").length + " dong, " + Math.round(fullCss.length / 1024) + " KB");

/* ---------- 2. JS du lieu ---------- */
var iWeeks = src.indexOf("var WEEKS = [");
var iEn = src.indexOf("var EN_WEEKS = [");
var iIv = src.indexOf("var IV_DATA = [");
if (iWeeks < 0 || iEn < 0 || iIv < 0) { throw new Error("khong tim thay mang du lieu"); }
var iIvEnd = src.indexOf("\nfunction ", iIv);
var dataJs = src.slice(iWeeks, iEn) + src.slice(iEn, iIv) + src.slice(iIv, iIvEnd);

/* ---------- 3. CHECK_ITEMS ---------- */
var ids = [];
var reCb = /<input type="checkbox" id="([^"]+)"/g, mCb;
while ((mCb = reCb.exec(src)) !== null) { ids.push(mCb[1]); }
log.push("CHECK_ITEMS: " + ids.length + " muc");

var engine = fs.readFileSync(path.join(ROOT, "_build/engine.js"), "utf8").replace(/\r\n/g, "\n");
var fullJs = "/* Roadmap .NET 2027 - du lieu + engine dung chung cho moi trang */\n"
    + dataJs
    + "var CHECK_ITEMS=" + JSON.stringify(ids) + ";\n"
    + engine;
fs.writeFileSync(path.join(ROOT, "assets/roadmap.js"), fullJs, "utf8");
log.push("assets/roadmap.js: " + fullJs.split("\n").length + " dong, " + Math.round(fullJs.length / 1024) + " KB");

/* ---------- 4. Tach section ---------- */
var sections = {};
var reSec = /<section id="([^"]+)">/g, mSec;
while ((mSec = reSec.exec(src)) !== null) {
    var open = mSec.index + mSec[0].length;
    var close = src.indexOf("</section>", open);
    sections[mSec[1]] = src.slice(open, close);
}
log.push("section tach duoc: " + Object.keys(sections).length);

/* ---------- 5. Tach sec-head khoi noi dung ---------- */
function splitSecHead(inner) {
    var re = /<div class="sec-head">\s*<div class="sec-num">\s*([^<]*?)\s*<\/div>\s*<div>\s*<h2>([\s\S]*?)<\/h2>\s*(?:<p>([\s\S]*?)<\/p>\s*)?<\/div>\s*<\/div>/;
    var mm = inner.match(re);
    if (!mm) { return { meta: null, body: inner }; }
    return {
        meta: { num: mm[1], title: mm[2], desc: mm[3] || "" },
        body: inner.replace(re, "")
    };
}
var secMeta = {};
var secBody = {};
Object.keys(sections).forEach(function (id) {
    var r = splitSecHead(sections[id]);
    secMeta[id] = r.meta;
    secBody[id] = r.body.replace(/^\n+/, "");
    if (!r.meta) { log.push("CANH BAO: khong tach duoc sec-head cua #" + id); }
});

/* ---------- 6. Tach schedule -> schedule + weekly ---------- */
var schedInner = secBody["schedule"];
var iWeeklyH3 = schedInner.indexOf('<h3 id="weekly">');
var iCardStart = schedInner.lastIndexOf('<div class="card"', iWeeklyH3);
secBody["schedule"] = schedInner.slice(0, iCardStart).replace(/\s+$/, "");
var weeklyGrid = '<div class="grid g2" id="weekContainer"></div>';
if (src.indexOf(weeklyGrid) < 0) { throw new Error("khong tim thay weekContainer"); }
secMeta["weekly"] = {
    num: "11",
    title: "Weekly cards - mục tiêu từng tuần",
    desc: "13 tuần · bấm vào từng tuần để mở kiến thức, thực hành, chủ đề English và deliverable."
};
secBody["weekly"] = weeklyGrid + "\n";
log.push("tach xong nhanh weekly khoi schedule");

/* ---------- 7. Tiem thanh tien do cho checklist project / cuoi tuan ---------- */
function meter(label, prefix) {
    return '<div class="row-meter">\n'
        + '<span class="rm-label">' + label + '</span>\n'
        + '<span class="rm-pct" id="' + prefix + 'PhaseText">0/0 - 0%</span>\n'
        + '<div class="bar sm"><span id="' + prefix + 'PhaseBar"></span></div>\n'
        + '</div>';
}
secBody["project"] = secBody["project"].replace(
    '<div class="check-list" data-phase="prj">',
    meter("Tiến độ checklist project", "prj") + '\n<div class="check-list" data-phase="prj">'
);
secBody["daily"] = secBody["daily"].replace(
    '<div class="check-list" data-phase="wk">',
    meter("Tiến độ checklist cuối tuần", "wk") + '\n<div class="check-list" data-phase="wk">'
);

/* ---------- 8. Cau hinh trang ---------- */
var STATS = '<div class="stats">\n'
    + '<div class="stat"><div class="s-label">Thời lượng</div><div class="s-value">13 tuần</div><div class="s-note">01/10 → 31/12/2026</div></div>\n'
    + '<div class="stat"><div class="s-label">Giờ / tuần</div><div class="s-value">15–17h</div><div class="s-note">Người đi làm full-time</div></div>\n'
    + '<div class="stat"><div class="s-label">Kinh nghiệm</div><div class="s-value">4 năm</div><div class="s-note">C# · WinForms · Web API · SQL · ERP</div></div>\n'
    + '<div class="stat"><div class="s-label">Target lương</div><div class="s-value">25–30tr</div><div class="s-note">Backend .NET / ERP Technical</div></div>\n'
    + '<div class="stat"><div class="s-label">Ngôn ngữ CV</div><div class="s-value">EN + VI</div><div class="s-note">Apply cả product &amp; outsource</div></div>\n'
    + '</div>';

function barRow(label, prefix, cls) {
    return '<div class="gp-head" style="margin-top:var(--space-4);margin-bottom:var(--space-2)">'
        + '<span>' + label + '</span>'
        + '<span id="' + prefix + 'Text">0%</span></div>\n'
        + '<div class="bar sm ' + (cls || "") + '"><span id="' + prefix + 'Bar"></span></div>';
}
var GLOBAL_PROGRESS = '<div class="global-progress" style="border-top:0;padding-top:0;margin-top:0">\n'
    + '<div class="gp-head"><b>Tiến độ hoàn thành roadmap</b><span id="gpText">0 / 0 mục — 0%</span></div>\n'
    + '<div class="bar"><span id="gpBar"></span></div>\n'
    + barRow("PHASE 1 — C# + ASP.NET Core + Web API", "p1", "bar-yellow")
    + barRow("PHASE 2 — EF Core + SQL + Auth + Architecture", "p2", "bar-violet")
    + barRow("PHASE 3 — Project + Vue + Docker + English + Job", "p3", "bar-green")
    + barRow("INTERVIEW — 100 câu hỏi", "iv", "bar-cyan")
    + '\n</div>';

var PAGES = [
    { key: "dashboard", file: "roadmap_dotnet_2027.html", num: "00", group: "Tổng quan", nav: "Toàn cảnh &amp; tiến độ", dates: "01/10 → 31/12/2026", actions: ["print", "reset"] },
    { key: "overview", file: "01-profile.html", num: "01", group: "Tổng quan", nav: "Profile &amp; mục tiêu", sec: "overview", dates: "3 tháng · 13 tuần", actions: ["print"] },
    { key: "flowchart", file: "02-flowchart.html", num: "02", group: "Tổng quan", nav: "Sơ đồ tổng quan", sec: "flowchart", dates: "Toàn cảnh lộ trình", actions: ["print"] },
    { key: "timeline", file: "03-timeline.html", num: "03", group: "Tổng quan", nav: "Timeline 3 tháng", sec: "timeline", dates: "3 phase · 13 tuần", actions: ["print"] },
    { key: "skillmatrix", file: "04-skill-matrix.html", num: "04", group: "Tổng quan", nav: "Skill matrix", sec: "skillmatrix", dates: "Trước &amp; sau 3 tháng", actions: ["print"] },
    { key: "phase1", file: "05-phase1.html", num: "05", group: "Lộ trình", nav: "Phase 1 — C# &amp; Web API", sec: "phase1", dates: "01/10 → 31/10/2026", tile: "21 mục checklist", meter: "tmP1", actions: ["print"] },
    { key: "phase2", file: "06-phase2.html", num: "06", group: "Lộ trình", nav: "Phase 2 — EF Core &amp; Auth", sec: "phase2", dates: "01/11 → 30/11/2026", tile: "20 mục checklist", meter: "tmP2", actions: ["print"] },
    { key: "phase3", file: "07-phase3.html", num: "07", group: "Lộ trình", nav: "Phase 3 — Project &amp; Job", sec: "phase3", dates: "01/12 → 31/12/2026", tile: "24 mục checklist", meter: "tmP3", actions: ["print"] },
    { key: "project", file: "08-project.html", num: "08", group: "Lộ trình", nav: "Project cuối khóa", sec: "project", dates: "Tuần 9 → 13", tile: "18 mục checklist", meter: "tmPrj", actions: ["print"] },
    { key: "architecture", file: "09-architecture.html", num: "09", group: "Lộ trình", nav: "Architecture", sec: "architecture", dates: "Thiết kế kỹ thuật", actions: ["print"] },
    { key: "schedule", file: "10-schedule.html", num: "10", group: "Luyện tập", nav: "Lịch học hằng ngày", sec: "schedule", dates: "15–17 giờ/tuần", actions: ["print"] },
    { key: "weekly", file: "11-weekly.html", num: "11", group: "Luyện tập", nav: "Weekly cards", sec: "weekly", dates: "13 tuần", tile: "13 tuần mục tiêu", actions: ["print", "weeks"] },
    { key: "english", file: "12-english.html", num: "12", group: "Luyện tập", nav: "English for .NET Dev", sec: "english", dates: "12 tuần · 85 câu mẫu", actions: ["print", "weeks"] },
    { key: "interview", file: "13-interview.html", num: "13", group: "Luyện tập", nav: "100 câu phỏng vấn", sec: "interview", dates: "100 câu · 4 mức", tile: "100 câu · 4 mức", meter: "tmIv", actions: ["print"] },
    { key: "daily", file: "14-daily.html", num: "14", group: "Luyện tập", nav: "Daily checklist", sec: "daily", dates: "Tự reset mỗi ngày", actions: ["print"] },
    { key: "jobprep", file: "15-job-prep.html", num: "15", group: "Ứng tuyển", nav: "Job preparation", sec: "jobprep", dates: "08/12/2026 → 01/2027", actions: ["print"] },
    { key: "target", file: "16-target.html", num: "16", group: "Ứng tuyển", nav: "Target job &amp; salary", sec: "target", dates: "25–30 triệu VND", actions: ["print"] }
];
var fileOf = {};
PAGES.forEach(function (p) { fileOf[p.key] = p.file; });
log.push("tong so trang: " + PAGES.length);

/* ---------- 9. Doi anchor noi dung sang link trang ---------- */
function rewriteAnchors(html) {
    return html.replace(/href="#([a-z0-9]+)"/g, function (all, id) {
        if (id === "main") { return all; }
        return fileOf[id] ? 'href="' + fileOf[id] + '"' : all;
    });
}

/* ---------- 10. Dieu huong ---------- */
var NAV_TITLE = {
    "Tổng quan": "Bắt đầu",
    "Lộ trình": "Lộ trình 3 phase",
    "Luyện tập": "Luyện tập",
    "Ứng tuyển": "Ứng tuyển"
};
function buildNav(current) {
    var groups = [];
    PAGES.forEach(function (p) {
        var g = groups.filter(function (x) { return x.name === p.group; })[0];
        if (!g) { g = { name: p.group, items: [] }; groups.push(g); }
        g.items.push(p);
    });
    var html = "";
    groups.forEach(function (g) {
        html += '<div class="nav-group">\n';
        html += '<div class="nav-title">' + (NAV_TITLE[g.name] || g.name) + '</div>\n';
        g.items.forEach(function (p) {
            html += '<a class="nav-link" data-nav="' + p.key + '" href="' + p.file + '"><i>' + p.num + '</i>' + p.nav + '</a>\n';
        });
        html += '</div>\n';
    });
    html += '<div class="side-progress">\n'
        + '<div class="sp-row"><span>Tiến độ tổng</span><span class="sp-val" id="sideProgress">0%</span></div>\n'
        + '<div class="bar sm"><span id="sideBar"></span></div>\n'
        + '<div class="sp-row" style="margin-top:var(--space-3)"><span>Đã hoàn thành</span><span id="sideCount">0/0</span></div>\n'
        + '</div>\n';
    return html;
}

/* ---------- 11. Nut hanh dong ---------- */
function actionsHTML(p) {
    var out = [];
    (p.actions || []).forEach(function (a) {
        if (a === "print") {
            out.push('<button class="btn btn-primary" type="button" onclick="window.print()">' + (p.key === "dashboard" ? "In roadmap" : "In trang này") + '</button>');
        } else if (a === "weeks") {
            out.push('<button class="btn" type="button" onclick="expandAllWeeks()">Mở tất cả tuần</button>');
        } else if (a === "reset") {
            out.push('<button class="btn btn-danger" type="button" onclick="resetProgress()">Xoá tiến độ</button>');
        }
    });
    return out.join("\n");
}

/* ---------- 12. Dau trang ---------- */
function topbarHTML(p, meta, idx) {
    var eyebrow, title, sub;
    if (p.key === "dashboard") {
        eyebrow = "Roadmap 2026 → 2027 · Backend .NET";
        title = "Ba tháng chuyển sang .NET hiện đại và ERP chuyên sâu.";
        sub = "01/10/2026 → 31/12/2026 · 4 năm kinh nghiệm · Target 25–30 triệu VND · Apply từ 01/2027";
    } else {
        eyebrow = p.group + " · Mục " + p.num;
        title = meta.title;
        sub = meta.desc;
    }
    var chips = (p.key === "dashboard")
        ? ['17 trang', '13 tuần', '03 phase', '100 câu hỏi']
        : ['Trang ' + (idx + 1) + '/17', p.dates, p.group];
    var html = '<div class="topbar' + (p.key === "dashboard" ? "" : " topbar-slim") + '">\n';
    html += '<div class="topbar-copy">\n<p class="eyebrow">' + eyebrow + '</p>\n';
    html += '<h1>' + title + (sub ? '\n<small>' + sub + '</small>' : '') + '</h1>\n</div>\n';
    html += '<div class="top-actions">\n' + actionsHTML(p) + '\n</div>\n';
    html += '<div class="hero-index" aria-hidden="true">\n';
    chips.forEach(function (c) { html += '<span>' + c + '</span>\n'; });
    html += '</div>\n</div>\n';
    return html;
}

/* ---------- 13. Pager ---------- */
function pagerHTML(idx) {
    var prev = PAGES[idx - 1];
    var next = PAGES[idx + 1];
    var html = '<nav class="pager" aria-label="Chuyển trang">\n';
    if (prev) {
        html += '<a class="pg-prev" href="' + prev.file + '"><span class="pg-label">← ' + prev.num + ' · Trang trước</span><span class="pg-title">' + prev.nav + '</span></a>\n';
    } else {
        html += '<span class="pg-blank"></span>\n';
    }
    if (next) {
        html += '<a class="pg-next" href="' + next.file + '"><span class="pg-label">' + next.num + ' · Trang sau →</span><span class="pg-title">' + next.nav + '</span></a>\n';
    } else {
        html += '<span class="pg-blank"></span>\n';
    }
    html += '</nav>\n';
    return html;
}

/* ---------- 14. Noi dung dashboard ---------- */
function tileHTML(p) {
    var html = '<a class="nav-tile" href="' + p.file + '">\n';
    html += '<span class="nt-num">' + p.num + ' <span>· ' + p.group + '</span></span>\n';
    html += '<b>' + p.nav + '</b>\n';
    html += '<p>' + p.dates + (p.tile ? ' · ' + p.tile : '') + '</p>\n';
    if (p.meter) {
        html += '<div class="nt-meter"><div class="bar sm"><span id="' + p.meter + '"></span></div><span class="nt-pct" id="' + p.meter + 'Text">0%</span></div>\n';
    }
    html += '</a>\n';
    return html;
}
function dashboardHTML() {
    var html = '<section id="dashboard">\n';
    html += GLOBAL_PROGRESS;
    var groups = [];
    PAGES.forEach(function (p) {
        if (p.key === "dashboard") { return; }
        var g = groups.filter(function (x) { return x.name === p.group; })[0];
        if (!g) { g = { name: p.group, items: [] }; groups.push(g); }
        g.items.push(p);
    });
    groups.forEach(function (g) {
        html += '<p class="group-label">' + g.name + '</p>\n';
        html += '<div class="grid g3">\n';
        g.items.forEach(function (p) { html += tileHTML(p); });
        html += '</div>\n';
    });
    html += '<div class="callout ok" style="margin-top:var(--space-7)">\n<span class="c-mark">Ghi chú</span>\n'
        + '<div><b>Cách dùng:</b> chọn một mục ở menu bên trái (hoặc một ô phía trên) để mở trang tương ứng. '
        + 'Tiến độ được lưu chung một chỗ, nên tick ở bất kỳ trang nào thì thanh tiến độ ở mọi trang đều cập nhật; '
        + 'nếu mở nhiều tab cùng lúc, các tab tự đồng bộ với nhau. '
        + 'Mỗi trang đều có nút <b>In trang này</b>; ở trang này có thêm <b>In roadmap</b> và <b>Xoá tiến độ</b>.</div>\n</div>\n';
    html += '</section>\n';
    return html;
}

/* ---------- 15. Xuat trang ---------- */
var SIDEBAR_BRAND = '<div class="brand">\n<div class="brand-logo">.NET</div>\n<div class="brand-text">\n<b>ROADMAP 2027</b>\n<span>01/10/2026 → 31/12/2026</span>\n</div>\n</div>\n';
