input.contents:
var fs = require("fs");
var path = require("path");
var cp = require("child_process");
var CHROME = "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe";
var ROOT = "g:/1.Lộ trình/code";
var BASE = "file:///G:/1.L%E1%BB%99%20tr%C3%ACnh/code/";
var UD = path.join(process.env.TEMP, "rdchrome-dom");

function dumpDom(file) {
    var args = ["--headless=new", "--disable-gpu", "--no-first-run", "--user-data-dir=" + UD,
        "--virtual-time-budget=3000", "--dump-dom", BASE + file];
    var out = cp.execFileSync(CHROME, args, { maxBuffer: 1024 * 1024 * 40, stdio: ["ignore", "pipe", "ignore"] });
    return out.toString("utf8");
}
function count(t, re) { return (t.match(re) || []).length; }
function pick(t, id) {
    var m = t.match(new RegExp('id="' + id + '">([^<]*)<'));
    return m ? m[1] : "(khong co)";
}

var pages = ["roadmap_dotnet_2027", "01-profile", "02-flowchart", "04-skill-matrix", "05-phase1",
    "07-phase3", "08-project", "11-weekly", "12-english", "13-interview", "14-daily", "16-target"];

var rows = [];
pages.forEach(function (p) {
    var t = dumpDom(p + ".html");
    rows.push([
        p,
        "sec=" + count(t, /<section id="/g),
        "nav=" + count(t, /class="nav-link"/g),
        "navOn=" + count(t, /nav-link active/g),
        "wk=" + count(t, /class="week-card"/g),
        "en=" + count(t, /class="en-line"/g),
        "iv=" + count(t, /class="iv-item"/g),
        "ivH=" + count(t, /data-ivhead/g),
        "chk=" + count(t, /type="checkbox"/g),
        "gp=" + pick(t, "gpText"),
        "side=" + pick(t, "sideProgress"),
        "p1=" + pick(t, "p1PhaseText"),
        "prj=" + pick(t, "prjPhaseText"),
        "wkp=" + pick(t, "wkPhaseText"),
        "body=" + (t.match(/<body[^>]*>/) || [""])[0]
    ].join(" | "));
});
console.log(rows.join("\n"));

